insert into public.translations (locale, key, value) values
  ('pt-BR', 'mods.required', $json$"Essencial"$json$::jsonb),
  ('en', 'mods.required', $json$"Essential"$json$::jsonb),
  ('es', 'mods.required', $json$"Esencial"$json$::jsonb),
  ('zh-CN', 'mods.required', $json$"必需"$json$::jsonb),
  ('hi', 'mods.required', $json$"ज़रूरी"$json$::jsonb),
  ('ar', 'mods.required', $json$"أساسية"$json$::jsonb),
  ('fr', 'mods.required', $json$"Essentiel"$json$::jsonb),
  ('ru', 'mods.required', $json$"Обязательный"$json$::jsonb),
  ('ja', 'mods.required', $json$"必須"$json$::jsonb),
  ('de', 'mods.required', $json$"Unverzichtbar"$json$::jsonb),
  ('pt-BR', 'mods.required.hint', $json$"O JayV precisa deste mod: ele fica instalado e ligado. O plano continua decidindo o que ele traz."$json$::jsonb),
  ('en', 'mods.required.hint', $json$"JayV needs this mod: it stays installed and on. Your plan still decides what it brings."$json$::jsonb),
  ('es', 'mods.required.hint', $json$"JayV necesita este mod: se queda instalado y activado. Tu plan sigue decidiendo lo que trae."$json$::jsonb),
  ('zh-CN', 'mods.required.hint', $json$"JayV 需要此模组：它始终保持安装并开启。套餐仍决定它带来的内容。"$json$::jsonb),
  ('hi', 'mods.required.hint', $json$"JayV को इस मॉड की ज़रूरत है: यह इंस्टॉल और चालू रहता है। यह जो लाता है वह अब भी आपका प्लान तय करता है।"$json$::jsonb),
  ('ar', 'mods.required.hint', $json$"يحتاج JayV إلى هذه الإضافة: تبقى مثبّتة ومفعّلة. وتظل خطتك هي التي تحدد ما تجلبه."$json$::jsonb),
  ('fr', 'mods.required.hint', $json$"JayV a besoin de ce mod : il reste installé et activé. Votre forfait décide toujours de ce qu’il apporte."$json$::jsonb),
  ('ru', 'mods.required.hint', $json$"Этот мод нужен JayV: он всегда установлен и включён. Что он добавляет, по-прежнему решает тариф."$json$::jsonb),
  ('ja', 'mods.required.hint', $json$"この Mod は JayV に必要です。常にインストール済みでオンのままです。何が使えるかは引き続きプランで決まります。"$json$::jsonb),
  ('de', 'mods.required.hint', $json$"JayV braucht diesen Mod: Er bleibt installiert und eingeschaltet. Was er mitbringt, entscheidet weiterhin Ihr Tarif."$json$::jsonb),
  ('pt-BR', 'mods.description', $json$"Mods acrescentam coisas ao JayV, como os mods de um jogo: motores de LLM, recursos, agentes e o que mais o app aprender a receber. Instale, ligue, desligue e desinstale cada um aqui; as mudanças valem quando você salva. Os essenciais, que são os recursos do app, ficam sempre instalados e ligados."$json$::jsonb),
  ('en', 'mods.description', $json$"Mods add to JayV, like mods in a game: LLM engines, features, agents and whatever the app learns to take next. Install, turn on, turn off and uninstall each one here; the changes apply when you save. The essential ones, the features of the app, always stay installed and on."$json$::jsonb),
  ('es', 'mods.description', $json$"Los mods añaden cosas a JayV, como los mods de un juego: motores de LLM, funciones, agentes y lo que la app aprenda a recibir después. Instala, activa, desactiva y desinstala cada uno aquí; los cambios valen al guardar. Los esenciales, que son las funciones de la app, siempre se quedan instalados y activados."$json$::jsonb),
  ('zh-CN', 'mods.description', $json$"模组为 JayV 增添内容，就像游戏里的模组：LLM 引擎、功能、智能体，以及应用今后能接收的其他内容。在这里安装、开启、关闭和卸载每个模组；保存后生效。必需模组（即应用的功能）始终保持安装并开启。"$json$::jsonb),
  ('hi', 'mods.description', $json$"मॉड JayV में चीज़ें जोड़ते हैं, जैसे किसी गेम के मॉड: LLM इंजन, सुविधाएँ, एजेंट और ऐप आगे जो भी लेना सीखे। हर एक को यहाँ इंस्टॉल, चालू, बंद और अनइंस्टॉल करें; बदलाव सहेजने पर लागू होते हैं। ज़रूरी मॉड, यानी ऐप की सुविधाएँ, हमेशा इंस्टॉल और चालू रहते हैं।"$json$::jsonb),
  ('ar', 'mods.description', $json$"تضيف الإضافات إلى JayV كما تفعل إضافات الألعاب: محركات LLM وميزات ووكلاء وكل ما يتعلم التطبيق استقباله لاحقًا. ثبّت كل إضافة وفعّلها وعطّلها وألغِ تثبيتها هنا؛ تسري التغييرات عند الحفظ. أما الإضافات الأساسية، وهي ميزات التطبيق، فتبقى دائمًا مثبّتة ومفعّلة."$json$::jsonb),
  ('fr', 'mods.description', $json$"Les mods ajoutent des choses à JayV, comme les mods d’un jeu : moteurs LLM, fonctionnalités, agents et tout ce que l’app saura recevoir ensuite. Installez, activez, désactivez et désinstallez chacun ici ; les changements s’appliquent à l’enregistrement. Les essentiels, c’est-à-dire les fonctionnalités de l’app, restent toujours installés et activés."$json$::jsonb),
  ('ru', 'mods.description', $json$"Моды добавляют возможности в JayV, как моды в играх: движки LLM, функции, агентов и всё, что приложение научится принимать дальше. Устанавливайте, включайте, выключайте и удаляйте каждый здесь; изменения вступают в силу после сохранения. Обязательные моды — функции приложения — всегда установлены и включены."$json$::jsonb),
  ('ja', 'mods.description', $json$"Mod はゲームの Mod のように JayV に機能を追加します。LLM エンジン、機能、エージェント、そして今後アプリが受け取れるようになるもの。ここで各 Mod をインストール、オン、オフ、アンインストールできます。変更は保存したときに反映されます。必須の Mod（アプリの機能）は常にインストール済みでオンのままです。"$json$::jsonb),
  ('de', 'mods.description', $json$"Mods erweitern JayV wie Mods in einem Spiel: LLM-Engines, Funktionen, Agenten und alles, was die App künftig aufnehmen kann. Installieren, einschalten, ausschalten und deinstallieren Sie jeden hier; Änderungen gelten beim Speichern. Die unverzichtbaren Mods – die Funktionen der App – bleiben immer installiert und eingeschaltet."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.requiredMods.title', $json$"Mods essenciais"$json$::jsonb),
  ('en', 'whatsNew.item.requiredMods.title', $json$"Essential mods"$json$::jsonb),
  ('es', 'whatsNew.item.requiredMods.title', $json$"Mods esenciales"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.requiredMods.title', $json$"必需模组"$json$::jsonb),
  ('hi', 'whatsNew.item.requiredMods.title', $json$"ज़रूरी मॉड"$json$::jsonb),
  ('ar', 'whatsNew.item.requiredMods.title', $json$"الإضافات الأساسية"$json$::jsonb),
  ('fr', 'whatsNew.item.requiredMods.title', $json$"Mods essentiels"$json$::jsonb),
  ('ru', 'whatsNew.item.requiredMods.title', $json$"Обязательные моды"$json$::jsonb),
  ('ja', 'whatsNew.item.requiredMods.title', $json$"必須の Mod"$json$::jsonb),
  ('de', 'whatsNew.item.requiredMods.title', $json$"Unverzichtbare Mods"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.requiredMods.detail', $json$"Os recursos do JayV agora são mods essenciais: ficam sempre instalados e ligados, e voltam se tinham sido desligados. Os motores de LLM (Claude Code, Codex, GitHub Copilot, Cursor, Kilo Code, OpenRouter, LiteLLM) e os agentes Ollama e LM Studio continuam podendo ser desligados e desinstalados em Configuração › Mods. O plano continua decidindo quais recursos você tem."$json$::jsonb),
  ('en', 'whatsNew.item.requiredMods.detail', $json$"The features of JayV are now essential mods: they always stay installed and on, and come back if they were turned off. The LLM engines (Claude Code, Codex, GitHub Copilot, Cursor, Kilo Code, OpenRouter, LiteLLM) and the agents Ollama and LM Studio can still be turned off and uninstalled in Settings › Mods. Your plan still decides which features you have."$json$::jsonb),
  ('es', 'whatsNew.item.requiredMods.detail', $json$"Las funciones de JayV ahora son mods esenciales: siempre se quedan instaladas y activadas, y vuelven si se habían desactivado. Los motores de LLM (Claude Code, Codex, GitHub Copilot, Cursor, Kilo Code, OpenRouter, LiteLLM) y los agentes Ollama y LM Studio se pueden seguir desactivando y desinstalando en Configuración › Mods. Tu plan sigue decidiendo qué funciones tienes."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.requiredMods.detail', $json$"JayV 的功能现在是必需模组：始终保持安装并开启，之前被关闭的会重新开启。LLM 引擎（Claude Code、Codex、GitHub Copilot、Cursor、Kilo Code、OpenRouter、LiteLLM）以及 Ollama 和 LM Studio 智能体仍可在“设置 › 模组”中关闭和卸载。套餐仍决定你拥有哪些功能。"$json$::jsonb),
  ('hi', 'whatsNew.item.requiredMods.detail', $json$"JayV की सुविधाएँ अब ज़रूरी मॉड हैं: वे हमेशा इंस्टॉल और चालू रहती हैं, और अगर बंद की गई थीं तो फिर चालू हो जाती हैं। LLM इंजन (Claude Code, Codex, GitHub Copilot, Cursor, Kilo Code, OpenRouter, LiteLLM) और Ollama व LM Studio एजेंट अब भी सेटिंग्स › मॉड में बंद और अनइंस्टॉल किए जा सकते हैं। आपके पास कौन-सी सुविधाएँ हैं, यह अब भी आपका प्लान तय करता है।"$json$::jsonb),
  ('ar', 'whatsNew.item.requiredMods.detail', $json$"أصبحت ميزات JayV إضافات أساسية: تبقى دائمًا مثبّتة ومفعّلة، وتعود إن كانت معطّلة. أما محركات LLM ‏(Claude Code وCodex وGitHub Copilot وCursor وKilo Code وOpenRouter وLiteLLM) والوكيلان Ollama وLM Studio فيمكن تعطيلها وإلغاء تثبيتها في الإعدادات › الإضافات. وتظل خطتك هي التي تحدد الميزات المتاحة لك."$json$::jsonb),
  ('fr', 'whatsNew.item.requiredMods.detail', $json$"Les fonctionnalités de JayV sont désormais des mods essentiels : elles restent toujours installées et activées, et reviennent si elles avaient été désactivées. Les moteurs LLM (Claude Code, Codex, GitHub Copilot, Cursor, Kilo Code, OpenRouter, LiteLLM) et les agents Ollama et LM Studio peuvent toujours être désactivés et désinstallés dans Configuration › Mods. Votre forfait décide toujours des fonctionnalités dont vous disposez."$json$::jsonb),
  ('ru', 'whatsNew.item.requiredMods.detail', $json$"Функции JayV теперь — обязательные моды: они всегда установлены и включены и возвращаются, если были выключены. Движки LLM (Claude Code, Codex, GitHub Copilot, Cursor, Kilo Code, OpenRouter, LiteLLM) и агенты Ollama и LM Studio по-прежнему можно выключать и удалять в Настройки › Моды. Какие функции вам доступны, по-прежнему решает тариф."$json$::jsonb),
  ('ja', 'whatsNew.item.requiredMods.detail', $json$"JayV の機能は必須の Mod になりました。常にインストール済みでオンのままで、オフにしていた場合も元に戻ります。LLM エンジン（Claude Code、Codex、GitHub Copilot、Cursor、Kilo Code、OpenRouter、LiteLLM）と、エージェントの Ollama と LM Studio は、引き続き設定 › Mod でオフやアンインストールができます。使える機能は引き続きプランで決まります。"$json$::jsonb),
  ('de', 'whatsNew.item.requiredMods.detail', $json$"Die Funktionen von JayV sind jetzt unverzichtbare Mods: Sie bleiben immer installiert und eingeschaltet und kommen zurück, falls sie ausgeschaltet waren. Die LLM-Engines (Claude Code, Codex, GitHub Copilot, Cursor, Kilo Code, OpenRouter, LiteLLM) und die Agenten Ollama und LM Studio lassen sich weiterhin unter Einstellungen › Mods ausschalten und deinstallieren. Welche Funktionen Sie haben, entscheidet weiterhin Ihr Tarif."$json$::jsonb),
  ('pt-BR', 'docs.modCatalog.usage', $json$"Abra Configuração › Mods. Em Instalados, ligue ou desligue cada mod, abra a configuração dele ou desinstale-o; em Disponíveis no catálogo, Instalar adiciona um mod (e os mods de que ele precisa). A busca filtra as duas listas pelo nome, pela descrição ou pelo autor. Os mods essenciais — os recursos do app — ficam sempre instalados e ligados, sem interruptor nem Desinstalar; os motores de LLM e os agentes (como Ollama e LM Studio) podem ser desligados e desinstalados. As mudanças valem quando você salva, neste ambiente e nos seus outros computadores; o site (Painel › Mods) mostra e muda os mesmos mods. Um mod que veio instalado não volta sozinho depois de desinstalado. Um mod que precisa de um JayV mais novo espera a atualização. O plano continua decidindo: o que ele não inclui fica desligado, e o que ele trava fica ligado. Também na paleta de comandos (Ctrl+K): Instalar mod, Ligar mod, Desligar mod e Desinstalar mod."$json$::jsonb),
  ('en', 'docs.modCatalog.usage', $json$"Open Settings › Mods. Under Installed, turn each mod on or off, open its settings or uninstall it; under Available in the catalog, Install adds a mod (and the mods it needs). Search filters both lists by name, description or author. The essential mods — the features of the app — always stay installed and on, without a switch or Uninstall; the LLM engines and the agents (like Ollama and LM Studio) can be turned off and uninstalled. The changes apply when you save, in this environment and on your other computers; the site (Dashboard › Mods) shows and changes the same mods. A mod that came installed does not come back on its own after you uninstall it. A mod that needs a newer JayV waits for the update. Your plan still decides: what it doesn't include stays off, and what it locks stays on. Also in the command palette (Ctrl+K): Install mod, Turn on mod, Turn off mod and Uninstall mod."$json$::jsonb),
  ('es', 'docs.modCatalog.usage', $json$"Abre Configuración › Mods. En Instalados, activa o desactiva cada mod, abre su configuración o desinstálalo; en Disponibles en el catálogo, Instalar añade un mod (y los mods que necesita). La búsqueda filtra ambas listas por nombre, descripción o autor. Los mods esenciales — las funciones de la app — siempre se quedan instalados y activados, sin interruptor ni Desinstalar; los motores de LLM y los agentes (como Ollama y LM Studio) se pueden desactivar y desinstalar. Los cambios valen al guardar, en este entorno y en tus otros equipos; el sitio (Panel › Mods) muestra y cambia los mismos mods. Un mod que vino instalado no vuelve solo después de desinstalarlo. Un mod que necesita un JayV más reciente espera la actualización. Tu plan sigue decidiendo: lo que no incluye queda desactivado y lo que bloquea queda activado. También en la paleta de comandos (Ctrl+K): Instalar mod, Activar mod, Desactivar mod y Desinstalar mod."$json$::jsonb),
  ('zh-CN', 'docs.modCatalog.usage', $json$"打开“设置 › 模组”。在“已安装”中开启或关闭每个模组、打开其设置或卸载；在“目录中可用”中，“安装”会添加一个模组（以及它依赖的模组）。搜索可按名称、描述或作者筛选两个列表。必需模组（即应用的功能）始终保持安装并开启，没有开关也没有“卸载”；LLM 引擎和智能体（如 Ollama 和 LM Studio）可以关闭和卸载。保存后，更改在此环境和你的其他电脑上生效；网站（控制台 › 模组）显示并修改相同的模组。预装的模组卸载后不会自动回来。需要更新版 JayV 的模组会等待更新。套餐仍然决定一切：不包含的保持关闭，锁定的保持开启。命令面板（Ctrl+K）中也有：安装模组、开启模组、关闭模组和卸载模组。"$json$::jsonb),
  ('hi', 'docs.modCatalog.usage', $json$"सेटिंग्स › मॉड खोलें। इंस्टॉल किए गए में हर मॉड को चालू या बंद करें, उसकी सेटिंग खोलें या उसे अनइंस्टॉल करें; कैटलॉग में उपलब्ध में, इंस्टॉल करें एक मॉड (और उसे चाहिए मॉड) जोड़ता है। खोज दोनों सूचियों को नाम, विवरण या लेखक से छाँटती है। ज़रूरी मॉड — ऐप की सुविधाएँ — हमेशा इंस्टॉल और चालू रहते हैं, बिना स्विच और बिना अनइंस्टॉल के; LLM इंजन और एजेंट (जैसे Ollama और LM Studio) बंद और अनइंस्टॉल किए जा सकते हैं। बदलाव सहेजने पर इस वातावरण और आपके दूसरे कंप्यूटरों पर लागू होते हैं; साइट (डैशबोर्ड › मॉड) वही मॉड दिखाती और बदलती है। पहले से इंस्टॉल आया मॉड अनइंस्टॉल करने के बाद अपने-आप वापस नहीं आता। जिस मॉड को JayV का नया संस्करण चाहिए वह अपडेट का इंतज़ार करता है। आपका प्लान अब भी तय करता है: जो उसमें शामिल नहीं वह बंद रहता है, और जो वह लॉक करता है वह चालू रहता है। कमांड पैलेट (Ctrl+K) में भी: मॉड इंस्टॉल करें, मॉड चालू करें, मॉड बंद करें और मॉड अनइंस्टॉल करें।"$json$::jsonb),
  ('ar', 'docs.modCatalog.usage', $json$"افتح الإعدادات › الإضافات. في المثبّتة، فعّل كل إضافة أو عطّلها، أو افتح إعداداتها أو ألغِ تثبيتها؛ وفي المتاحة في الفهرس، يضيف «تثبيت» إضافةً (والإضافات التي تحتاج إليها). يصفّي البحث القائمتين بالاسم أو الوصف أو المؤلف. تبقى الإضافات الأساسية — وهي ميزات التطبيق — مثبّتة ومفعّلة دائمًا، بلا مفتاح ولا «إلغاء التثبيت»؛ أما محركات LLM والوكلاء (مثل Ollama وLM Studio) فيمكن تعطيلها وإلغاء تثبيتها. تسري التغييرات عند الحفظ، في هذه البيئة وعلى أجهزتك الأخرى؛ ويعرض الموقع (لوحة التحكم › الإضافات) الإضافات نفسها ويغيّرها. الإضافة التي جاءت مثبّتة لا تعود وحدها بعد إلغاء تثبيتها. والإضافة التي تحتاج إلى إصدار أحدث من JayV تنتظر التحديث. تظل خطتك هي الحاكمة: ما لا تتضمنه يبقى معطّلًا، وما تقفله يبقى مفعّلًا. وفي لوحة الأوامر (Ctrl+K) أيضًا: تثبيت الإضافة، وتفعيل الإضافة، وتعطيل الإضافة، وإلغاء تثبيت الإضافة."$json$::jsonb),
  ('fr', 'docs.modCatalog.usage', $json$"Ouvrez Configuration › Mods. Dans Installés, activez ou désactivez chaque mod, ouvrez ses réglages ou désinstallez-le ; dans Disponibles dans le catalogue, Installer ajoute un mod (et les mods dont il a besoin). La recherche filtre les deux listes par nom, description ou auteur. Les mods essentiels — les fonctionnalités de l’app — restent toujours installés et activés, sans interrupteur ni Désinstaller ; les moteurs LLM et les agents (comme Ollama et LM Studio) peuvent être désactivés et désinstallés. Les changements s’appliquent à l’enregistrement, dans cet environnement et sur vos autres ordinateurs ; le site (Tableau de bord › Mods) affiche et modifie les mêmes mods. Un mod fourni installé ne revient pas tout seul après sa désinstallation. Un mod qui demande un JayV plus récent attend la mise à jour. Votre forfait décide toujours : ce qu’il n’inclut pas reste désactivé, et ce qu’il verrouille reste activé. Aussi dans la palette de commandes (Ctrl+K) : Installer le mod, Activer le mod, Désactiver le mod et Désinstaller le mod."$json$::jsonb),
  ('ru', 'docs.modCatalog.usage', $json$"Откройте Настройки › Моды. В разделе «Установленные» включайте и выключайте каждый мод, открывайте его настройки или удаляйте его; в разделе «Доступно в каталоге» кнопка «Установить» добавляет мод (и нужные ему моды). Поиск фильтрует оба списка по названию, описанию или автору. Обязательные моды — функции приложения — всегда установлены и включены, без переключателя и без «Удалить»; движки LLM и агентов (например, Ollama и LM Studio) можно выключать и удалять. Изменения вступают в силу после сохранения — в этом окружении и на других ваших компьютерах; сайт (Панель › Моды) показывает и меняет те же моды. Предустановленный мод после удаления сам не возвращается. Мод, которому нужна более новая версия JayV, ждёт обновления. Тариф по-прежнему решает: то, чего в нём нет, остаётся выключенным, а то, что он закрепляет, — включённым. Также в палитре команд (Ctrl+K): «Установить мод», «Включить мод», «Выключить мод» и «Удалить мод»."$json$::jsonb),
  ('ja', 'docs.modCatalog.usage', $json$"設定 › Mod を開きます。「インストール済み」では各 Mod のオン／オフ、設定の表示、アンインストールができます。「カタログで利用可能」では「インストール」で Mod（と必要な Mod）を追加します。検索で両方の一覧を名前、説明、作者で絞り込めます。必須の Mod（アプリの機能）は常にインストール済みでオンのままで、スイッチも「アンインストール」もありません。LLM エンジンとエージェント（Ollama や LM Studio など）はオフやアンインストールができます。変更は保存したときに、この環境とほかのコンピューターに反映されます。サイト（ダッシュボード › Mod）でも同じ Mod を表示・変更できます。最初からインストールされていた Mod は、アンインストールすると自動では戻りません。より新しい JayV が必要な Mod はアップデートを待ちます。プランは引き続き適用され、含まれないものはオフ、固定されたものはオンのままです。コマンドパレット（Ctrl+K）でも「Mod をインストール」「Mod をオン」「Mod をオフ」「Mod をアンインストール」が使えます。"$json$::jsonb),
  ('de', 'docs.modCatalog.usage', $json$"Öffnen Sie Einstellungen › Mods. Unter „Installiert“ schalten Sie jeden Mod ein oder aus, öffnen seine Einstellungen oder deinstallieren ihn; unter „Im Katalog verfügbar“ fügt „Installieren“ einen Mod (und die Mods, die er benötigt) hinzu. Die Suche filtert beide Listen nach Name, Beschreibung oder Autor. Die unverzichtbaren Mods – die Funktionen der App – bleiben immer installiert und eingeschaltet, ohne Schalter und ohne „Deinstallieren“; die LLM-Engines und die Agenten (wie Ollama und LM Studio) lassen sich ausschalten und deinstallieren. Änderungen gelten beim Speichern, in dieser Umgebung und auf Ihren anderen Computern; die Website (Dashboard › Mods) zeigt und ändert dieselben Mods. Ein vorinstallierter Mod kommt nach dem Deinstallieren nicht von selbst zurück. Ein Mod, der ein neueres JayV benötigt, wartet auf das Update. Ihr Tarif entscheidet weiterhin: Was er nicht enthält, bleibt aus, und was er sperrt, bleibt an. Auch in der Befehlspalette (Strg+K): Mod installieren, Mod einschalten, Mod ausschalten und Mod deinstallieren."$json$::jsonb)
